"""Generate trial_e.py from trial_d.py: replay of the Study E rules (belief variants, debounce2) and a
per-trial count of false revocations (a goal leaves the verified set while the independent score says satisfied)."""
from pathlib import Path
HERE = Path(__file__).resolve().parent
SUBS = [
 ("# GENERATED by make_trial_d.py from ../v10_studyC/analyze.py - do not edit\n",
  "# GENERATED by make_trial_e.py from trial_d.py (itself generated from ../v10_studyC/analyze.py) - do not edit\n"),
 ("from study_d_rules import belief_step, error_now, BELIEF_PARAMS as P  # noqa: E402  (Study D)\n",
  "from study_d_rules import belief_step, error_now, BELIEF_PARAMS as P  # noqa: E402  (Study D)\nfrom study_e_rules import replay_new, replay_commit, replay_refresh  # noqa: E402  (Study E)\n"),
 ("RUN = HERE/'results/formal_D'\nEXEC = HERE/'execution/formal_D'\n", "RUN = HERE/'results/formal_E'\nEXEC = HERE/'execution/formal_E'\n"),
 ("    deferrals = requested = outside = reobs = 0; bel = {}; prev_err = {}\n",
  "    deferrals = requested = outside = reobs = fr = 0; bel = {}; prev_err = {}; rst = replay_new()\n"),
 ("            committed.add(e['goal_id']); bel[e['goal_id']] = max(bel.get(e['goal_id'], 0.0), P['b_commit'])\n",
  "            committed.add(e['goal_id']); bel[e['goal_id']] = max(bel.get(e['goal_id'], 0.0), P['b_commit']); replay_commit(unit['rule'], rst, e['goal_id'])\n"),
 ("            if rule == 'belief':\n",
  "            ep = replay_refresh(rule, rst, last_ctrl)\n            if ep is not None:\n                pred = ep\n            elif rule == 'belief':\n"),
 ("            replay_ok &= set(e['retained']) == pred and set(e['invalidated']) == set(e['before'])-pred\n",
  "            replay_ok &= set(e['retained']) == pred and set(e['invalidated']) == set(e['before'])-pred\n"
  "            fr += sum(1 for g in e['invalidated'] if any(x['goalId'] == g and x['satisfied'] for x in last_pair['score']['goals']))\n"),
 ("'workspace_cancellations': outside, 'belief_reobservations': reobs}",
  "'workspace_cancellations': outside, 'belief_reobservations': reobs, 'false_revocations': fr}"),
]


def main():
    s = (HERE/'trial_d.py').read_text(encoding='utf-8')
    for a, b in SUBS:
        assert s.count(a) == 1, a[:70]
        s = s.replace(a, b)
    (HERE/'trial_e.py').write_text(s, encoding='utf-8'); print('trial_e.py generated with', len(SUBS), 'substitutions')


if __name__ == '__main__':
    main()
